#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
/* ex07：FCFS / SSTF / SCAN / C-SCAN 四种磁盘调度的总寻道距离
 *
 * 关键口径（考研最容易扣分的地方）：
 *   - SCAN 的「回程」是**继续服务**请求的，走过的路都要算；
 *   - C-SCAN 的「回程」是**空返**（谁也不服务），但磁头确实跑了这段路，
 *     按「磁头真实移动距离」算时必须计入（本题 199 磁道）；
 *     有些教材只累加「服务请求」的移动量，那是另一种口径 —— 别混着比。
 * 本程序把两种口径都打印出来，让差异一目了然。*/
static int cmp(const void *a, const void *b) { return *(const int *)a - *(const int *)b; }

int main(void) {
    int req[] = {98, 183, 37, 122, 14, 124, 65, 67};
    int n = 8, head = 53, disk_max = 199;
    qsort(req, n, sizeof(int), cmp);

    /* ---- FCFS：按请求到达顺序服务（题面原始顺序）---- */
    int fcfs_seq[] = {98, 183, 37, 122, 14, 124, 65, 67};
    int total_fcfs = 0, cur = head;
    for (int i = 0; i < n; i++) { total_fcfs += abs(fcfs_seq[i] - cur); cur = fcfs_seq[i]; }

    /* ---- SSTF：每次挑离当前磁头最近的未服务请求（贪心，可能饥饿）---- */
    int done[8] = {0}, total_sstf = 0; cur = head;
    for (int k = 0; k < n; k++) {
        int best = -1, bestd = INT_MAX;
        for (int i = 0; i < n; i++)
            if (!done[i] && abs(req[i] - cur) < bestd) { bestd = abs(req[i] - cur); best = i; }
        total_sstf += bestd; cur = req[best]; done[best] = 1;
    }

    /* ---- SCAN（电梯）：向大扫到 199，再折返服务较小请求 ---- */
    int total_scan = 0; cur = head;
    for (int i = 0; i < n; i++) if (req[i] >= head) { total_scan += abs(req[i] - cur); cur = req[i]; }
    total_scan += abs(disk_max - cur); cur = disk_max;              /* 扫到磁盘末端 */
    for (int i = n - 1; i >= 0; i--) if (req[i] < head) { total_scan += abs(req[i] - cur); cur = req[i]; }

    /* ---- C-SCAN：向大扫到 199，空返 0，再向大服务剩下的 ---- */
    int cur2 = head, up_serve = 0, down_serve = 0, max_down = 0, i;
    for (i = 0; i < n; i++) if (req[i] >= head) { up_serve += abs(req[i] - cur2); cur2 = req[i]; }
    up_serve += abs(disk_max - cur2);                 /* 扫到 199，这段仍属「服务行程」 */
    for (i = 0; i < n; i++) if (req[i] < head && req[i] > max_down) max_down = req[i];
    down_serve = max_down;                            /* 从 0 出发服务到最大的较小请求 */
    int serve_cscan = up_serve + down_serve;          /* 只算服务行程的口径 */
    int total_cscan = serve_cscan + disk_max;         /* 再加 199 磁道空返（磁头真实移动） */

    printf("请求序列(已排序): ");
    for (i = 0; i < n; i++) printf("%d ", req[i]);
    printf("\n初始磁头=%d 磁盘 0..%d 初始方向=向大\n\n", head, disk_max);
    printf("%-10s %s\n", "算法", "总寻道距离(磁道)");
    printf("----------------------------\n");
    printf("%-10s %d\n", "FCFS", total_fcfs);
    printf("%-10s %d\n", "SSTF", total_sstf);
    printf("%-10s %d\n", "SCAN", total_scan);
    printf("%-10s %d  (含 199 磁道空返)\n", "C-SCAN", total_cscan);
    printf("\n口径对照：C-SCAN 若只算服务行程（%d 上扫 + %d 下扫）= %d；\n",
           up_serve, down_serve, serve_cscan);
    printf("          按磁头真实移动（含空返 199）= %d。做题先看题干用哪种口径。\n", total_cscan);
    printf("\n结论：SCAN/C-SCAN 多走「到端点」那段，换来等待时间可预测；\n");
    printf("      C-SCAN 总路程比 SCAN 更长（多出空返），但每条磁道的等待上界一致；\n");
    printf("      SSTF 平均最短却可能饿死远端请求 —— 平均寻道最短 != 体验最好。\n");
    printf("      现代磁盘固件内部做类似重排（TCQ/NCQ），OS 层已很少显式调度。\n");
    return 0;
}
